const KEY='thap-vo-tan-v1',app=document.querySelector('#app'),modalRoot=document.querySelector('#modal-root');
let state=E.createState(),page='home',filter='all',selectedHero=null,selectedEnemy=null,auto=false,busy=false,modalOpen=false,importCandidate=null,saveWarning=false;
let hallTab='equipment',gearHero='rook',gearFilter='all',trialWeek=null,dungeonTier=1;
let resultToken=0,pendingResult=null;
let recovered=false,suspended=false,practice=null,huntTier=1,craftKind='sets',craftSet='bastion',craftHero='rook';
let voyageConfig={mission:'mist-path',hero:'ember',slot:0},expeditionTimer;
