let summonFilter='all',summonShopFilter='all',pendingHeroExchange=null;
let tutorialDialog='other',pendingNoviceSsr=null;
let pendingContract=null;
let pendingCounter=null,pendingBattleTarget=null;
let pendingSmartGear=null;
let pendingGearPreset=null;
let pendingTeamPreset=null;
let pendingRefining=null,refiningDialogId=0;
let pendingBond=null,bondDialogId=0;
